UPDATE apr92_appr_modi
   SET apr92_reason = #{reason}
     , apr92_reg_date = f_sysdate()
 WHERE apr92_appr_modi_id = #{apprModiId}

UPDATE apr01_appr
   SET apr01_title        = #{r.title}
     , apr01_receive_nm   = #{r.receiveName}
     , apr01_reference_nm = #{r.referenceName}
     , apr01_note         = #{r.note}
     , apr01_sign_company = #{r.signCompany}
     , apr01_sign_ceo     = #{r.signCeo}
     , apr01_content      = #{content}
 WHERE apr01_appr_id    = #{apprId}
   AND apr01_company_id = #{companyId}

UPDATE apr50_bookmark
   SET apr50_public_yn = #{publicYn}
 WHERE apr50_appr_id = #{apprId}
   AND apr50_person_id IS NULL

